// Hàm làm sạch thông báo cho người dùng cuối (loại bỏ HTML, đường dẫn kỹ thuật, câu lệnh CLI)
function toCleanUserText(raw) {
  if (!raw) return '';
  return String(raw)
    .replace(/<!DOCTYPE[^>]*>[\s\S]*?<\/html>/gi, 'Dịch vụ đích phản hồi lỗi kết nối.')
